    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Serpentin.html&quot; title=&quot;Lignage Serpentin&quot;&gt;Serpentin&lt;/a&gt; (MJRA)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Des-Temp&#234;tes.html&quot; title=&quot;Lignage des Temp&#234;tes&quot;&gt;Temp&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Verdoyant.html&quot; title=&quot;Lignage Verdoyant&quot;&gt;Verdoyant&lt;/a&gt; (MJRA)&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Vou&#233;-&#192;-Un-Grand-Destin.html&quot; title=&quot;Lignage Vou&#233; &#224; un grand destin&quot;&gt;Vou&#233; &#224; un grand destin&lt;/a&gt;&lt;/li&gt;
